WITH enriched AS (SELECT a.id, a.manager_id, a.job_title, a.is_remote, a.level, p.full_name AS employee_full_name FROM employees a LEFT JOIN employees p ON a.manager_id <=> p.id WHERE p.hire_date < '2024-04-11'), cleaned AS (SELECT id, manager_id, job_title, is_remote, CONCAT_WS(',', level, job_title) level_job_title_key, COALESCE(level, 'DIRECT') level_clean FROM enriched WHERE job_title IS NOT NULL), enriched_employees AS (SELECT a.id, a.manager_id, p.level, p.email, p.salary FROM cleaned a LEFT JOIN employees p ON a.manager_id = p.id), cleaned_employees AS (SELECT *, LOWER(level) level_lower FROM enriched_employees WHERE manager_id IS NOT NULL), deduped AS (SELECT * FROM cleaned_employees QUALIFY ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary DESC, id) = 1), ranked AS (SELECT * FROM deduped QUALIFY ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary DESC, id) = 1) SELECT id, manager_id, email, salary, level_lower FROM ranked ORDER BY manager_id DESC, salary
